def solve(inp):
    h=len(inp); w=len(inp[0])
    from collections import Counter
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    orient=None; linecol=None; lcolv=None
    for j in range(w):
        col={inp[i][j] for i in range(h)}
        if len(col)==1 and next(iter(col))!=bg:
            linecol=j; lcolv=next(iter(col)); orient='v'
    if orient is None:
        for i in range(h):
            row={inp[i][j] for j in range(w)}
            if len(row)==1 and next(iter(row))!=bg:
                linecol=i; lcolv=next(iter(row)); orient='h'
    cells=[(i,j) for i in range(h) for j in range(w) if inp[i][j] not in (bg,lcolv)]
    bcol=inp[cells[0][0]][cells[0][1]]
    r0,r1=min(i for i,j in cells),max(i for i,j in cells)
    c0,c1=min(j for i,j in cells),max(j for i,j in cells)
    out=[[bg]*w for _ in range(h)]
    if orient=='v':
        for i in range(h): out[i][linecol]=lcolv
        s=(linecol+1)-c0
        for i,j in cells: out[i][j+s]=bcol
        for i in range(h): out[i][c1+s+1]=8
    else:
        for j in range(w): out[linecol][j]=lcolv
        s=(linecol+1)-r0
        for i,j in cells: out[i+s][j]=bcol
        for j in range(w): out[r1+s+1][j]=8
    return out
